import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Types-of-Commands.md","filePath":"manual-en/Types-of-Commands.md","lastUpdated":1785684581000}'),s={name:"manual-en/Types-of-Commands.md"};function n(i,a,p,d,m,f){return t(),o("div",null,[...a[0]||(a[0]=[r('<h3 id="_6-4-types-of-commands" tabindex="-1">6.4 Types of Commands <a class="header-anchor" href="#_6-4-types-of-commands" aria-label="Permalink to &quot;6.4 Types of Commands&quot;">​</a></h3><p>Commands in PSPP are divided roughly into six categories:</p><p><strong>Utility commands</strong></p><p>Set or display various global options that affect PSPP operations. May appear anywhere in a syntax file. See <a href="./Utilities">Utility commands</a>.</p><p><strong>File definition commands</strong></p><p>Give instructions for reading data from text files or from special binary “system files”. Most of these commands replace any previous data or variables with new data or variables. At least one file definition command must appear before the first command in any of the categories below. See <a href="./Data-Input-and-Output">Data Input and Output</a>.</p><p><strong>Input program commands</strong></p><p>Though rarely used, these provide tools for reading data files in arbitrary textual or binary formats. See <a href="./INPUT-PROGRAM">INPUT PROGRAM</a>.</p><p><strong>Transformations</strong></p><p>Perform operations on data and write data to output files. Transformations are not carried out until a procedure is executed.</p><p><strong>Restricted transformations</strong></p><p>Transformations that cannot appear in certain contexts. See <a href="./Order-of-Commands">Order of Commands</a>, for details.</p><p><strong>Procedures</strong></p><p>Analyze data, writing results of analyses to the listing file. Cause transformations specified earlier in the file to be performed. In a more general sense, a <em>procedure</em> is any command that causes the active dataset (the data) to be read.</p>',14)])])}const u=e(s,[["render",n]]);export{c as __pageData,u as default};
